    plan: [[-k.W / 2, zT], [k.W / 2, zT], [k.W / 2, zN - k.chamfer], [k.W / 2 - k.chamfer, zN], [k.chamfer - k.W / 2, zN], [-k.W / 2, zN - k.chamfer]],
